  'demo.idea.6': '洞察 → 團隊：誰負責什麼、哪些已逾期，以及和每個人一對一面談的檢視。工作 → 時間軸顯示接下來幾週。',
  'demo.idea.7': '客戶 → 業務檢視：誰的檢視已逾期或即將到來。按「完成」記錄一次檢視，下次日期隨之往後。節奏在 設定 → 目標與節奏 中設定。',
  'demo.idea.8': '在「客戶成功 — 綜合」看板上開啟一個任務：追蹤、關聯一個任務（「等待」）、花費時間、清單，以及底部的歷史。也試試看板上的篩選和檢視。',
  "demo.idea.9": "在客戶頁面上，「套用行動手冊」一鍵加入導入任務。",
  'demo.idea.10': '刪除一個任務或客戶，然後在底部的通知中選「復原」，或從你的選單開啟垃圾桶。刪除的內容會保留 30 天，並連同底下的一切一起還原。',
  'demo.idea.11': '左下角的 CuraAI：用你自己的話提問（例如「怎麼匯入客戶？」）。答案來自說明文件，並附上出處。',
  'demo.idea.12': '設定 → CRM 與試算表：連接一個 CRM。一個帶有虛構資料的模擬 CRM 會走完真實的步驟：授權、選擇要帶過來的內容、對應欄位、開始第一次同步。',
  'demo.idea.13': '開啟一個客戶（例如維途交通）：在時間軸上記錄一通電話，再看看健康評分旁的「為什麼？」。',
  'demo.idea.14': '設定 → 健康評分：調整權重，預覽會立刻顯示每個客戶的分數。',
