  "demo.tour.handover.1.title": "依階段查看交易",
  "demo.tour.handover.1.body": "每一欄是一個階段。交易贏單後拖到「贏單」。",
  "demo.tour.handover.2.title": "交易帶著來龍去脈",
  "demo.tour.handover.2.body": "誰參與過、承諾了什麼、何時續約，都留在交易裡，交給下一位接手的人。",
  'demo.tour.handover.3.title': "客戶團隊的檢視",
  'demo.tour.handover.3.body': "贏單的那一刻，客戶就出現在這裡：負責人、健康度和下一個承諾都在一張卡片上。",
  'demo.tour.handover-loop.title': "從贏單到「為你做好了」",
  'demo.tour.handover-loop.blurb': "銷售贏單時的交接卡片、連結到產品工作的客戶需求，以及上線時寄給客戶的訊息。",
  'demo.tour.handover-loop.1.title': "銷售剛剛贏下這一單",
  'demo.tour.handover-loop.1.body': "Cedarmoor Health 在銷售管道裡簽了兩年續約。打開這個客戶。",
  'demo.tour.handover-loop.2.title': "一張卡片，什麼都不漏",
  'demo.tour.handover-loop.2.body': "相關人員和他們的態度、銷售做過的承諾、他們還在等產品團隊交付的東西、各個日期，以及銷售往來的最新內容。沒有人需要另外去寫。",
  'demo.tour.handover-loop.3.title': "確認，就有了負責人",
  "demo.tour.handover-loop.3.body": "選擇在客戶成功（如果公司啟用了客戶導入，就在客戶導入）由誰接手，以及要啟動的行動手冊。在卡片任何位置按 Ctrl+Enter 也能確認。",
  'demo.tour.handover-loop.4.title': "一個提過需求的客戶",
  'demo.tour.handover-loop.4.body': "Quillfield Retail 向產品團隊提了兩項需求。打開它。",
  'demo.tour.handover-loop.5.title': "他們在等什麼",
  'demo.tour.handover-loop.5.body': "承諾和他們要的產品工作：狀態、衝刺結束日期和所屬部門。看得到這個客戶的人都看得到，不必打開產品團隊的看板。",
  'demo.tour.handover-loop.6.title': "已上線：告訴他們",
  'demo.tour.handover-loop.6.body': "工作完成後，負責人收到一個任務和這則訊息草稿。把它複製到郵件裡，或關閉他們在入口網站的請求。不會自動寄出任何內容。",
  'demo.tour.handover-loop.7.title': "連結下一個需求",
  'demo.tour.handover-loop.7.body': "搜尋產品團隊的工作，按兩下鍵就能連結需求。產品待辦清單隨即顯示有多少客戶在等、他們的價值，以及誰最快續約。",
  'demo.tour.move-in.title': "帶上你自己的檔案",
  'demo.tour.move-in.blurb': "拖入你現在所用工具的匯出檔，在 Curahold 中看到自己的工作。示範中檔案不會離開你的裝置。",
  'demo.tour.move-in.1.title': "任何匯出檔，一個入口",
  'demo.tour.move-in.1.body': "把 CSV、Excel 試算表或看板的 JSON 匯出檔拖到這裡。Curahold 會依欄名區分客戶和任務。",
  'demo.tour.move-in.2.title': "檔案只留在你這裡",
  'demo.tour.move-in.2.body': "整個示範都在這個瀏覽器分頁中執行。不會上傳任何內容，重新整理頁面即清除。",
  'demo.tour.move-in.3.title': "儲存之前先檢查",
  'demo.tour.move-in.3.body': "子任務、留言、自訂欄位和「等待」關聯也會一起匯入。試跑會告訴你哪些會匯入、哪些不會，四十個清單會合併成幾個部門看板。",
  'demo.tour.team-load.title': "誰有餘力，哪個客戶在等",
  'demo.tour.team-load.blurb': "逐人查看未來幾週，以及每個客戶的未完成工作、請求和工單，盡在一頁。",
