  "whatsapp.addHint": "客戶傳到你自己號碼的訊息會顯示在他們的頁面上，你可以直接回覆。使用你自己的 Meta 帳號：訊息費用由 Meta 向你收取，Curahold 不另外收費。",
  "support.what.whatsapp": "客戶傳到你的 WhatsApp Business 號碼的訊息，以及你的回覆。",
  "support.how.whatsapp": "在 Meta for Developers 中：你的應用程式 → WhatsApp → API Setup（電話號碼 ID），Business settings → System users（具 whatsapp_business_messaging 權限的永久權杖），App settings → Basic（應用程式密鑰）。",
