  "hooks.how.curahold": "在 Zapier 中用「Webhooks by Zapier → POST」，在 Make 中用「HTTP → Make a request」。對請求本文簽名：X-Curahold-Signature: t=<unix 秒>,v1=<用密鑰對 \"t.body\" 計算的 hex HMAC-SHA256>。加上 X-Curahold-Event-Id，重試只會被使用一次。",
  "hooks.how.esign": "在 DocuSign 中：Settings → Connect → Add Configuration → Custom。把位址貼為 URL to publish，選擇 JSON，勾選 Envelope Sent、Completed、Declined 和 Voided，並用你在這裡填寫的金鑰開啟 HMAC。",
  "hooks.how.aircall": "在 Aircall 中：Integrations → Webhook → Install。貼上位址，勾選 call.ended，再把 Webhook 的 token 貼到這裡。",
  "hooks.how.tawkto": "在 Tawk.to 中：Administration → Settings → Webhooks → Create webhook。貼上位址，勾選 Chat end 和 Ticket create，並把它的 secret key 貼到這裡。",
  "hooks.how.razorpay": "在 Razorpay 中：Accounts & Settings → Webhooks → Add New Webhook。貼上位址，填寫一個密鑰（這裡填同一個），勾選 payment.captured 和 payment.failed。",
  "hooks.how.custom": "把 JSON 傳送到該位址，並把密鑰放在 X-Curahold-Token 標頭中（工具無法設定標頭時，在位址後加 ?token=）。",
